 const config=(profile='DUAL_WEIGHBRIDGE',driver='PRELOADED_ROSTER',mode='NONE'):any=>({schemaVersion:1,loadingMeasurementMode:['DUAL_WEIGHBRIDGE','LOADING_SCALE_ONLY'].includes(profile)?'WEIGHBRIDGE':'NONE',unloadingMeasurementMode:['DUAL_WEIGHBRIDGE','UNLOADING_SCALE_ONLY'].includes(profile)?'WEIGHBRIDGE':'NONE',driverIntakeMode:driver,routeConfiguration:{loadingLocation:'Origin',unloadingLocation:'Destination',expectedTravelMinutes:30},shiftConfiguration:{mode:'NONE'},capacityEstimationPolicy:mode==='PROJECT_STANDARD'?{mode,tonnes:20}:{mode},requiredCheckpoints:[]});
