 const configure=async(p=page,token='SUPER_ADMIN')=>p.evaluate(async({company,projectId,token,uid}:any)=>{const w=window as any;w.clock=Date.now();w.token=token;w.principal=uid;w.transport=new w.lib.SqlOfflineHttpTransport(()=>w.principal?{uid:w.principal,getIdToken:async()=>w.token}:null);w.store=new w.lib.SqlOfflineStore();w.queue=new w.lib.SqlOfflineCoordinator(w.store,w.transport,()=>w.principal,()=>w.clock);await w.queue.enter(company,projectId);},{company,projectId:scope.projectId,token,uid:actors[token]});
 const enqueue=async(p=page,patch:any={})=>{await setConfig(config('NO_WEIGHBRIDGE','MIXED'));const refs=await fleet(false);return p.evaluate(async({refs,patch}:any)=>{const w=window as any;return w.queue.enqueue('TRIP','DISPATCH_TRIP',{...refs,...patch});},{refs,patch});};
 const tick=async(p=page,ms=60000)=>p.evaluate((ms:number)=>(window as any).clock+=ms,ms);
