 beforeAll(async()=>{
  temp=await mkdtemp(join(tmpdir(),'qsa-u07-'));const output=join(temp,'client.js');await build({entryPoints:['src/tests/helpers/sqlOfflineBrowserEntry.ts'],bundle:true,platform:'browser',format:'esm',outfile:output});bundle=await readFile(output,'utf8');
  importService=new SqlImportAuthority({...deps,sourceStore:new IsolatedSqlImportSourceStore()});const app=express();app.use(express.json({limit:'100kb'}));
  app.get('/',(_req,res)=>res.type('html').send('<!doctype html><title>U07 isolated browser acceptance</title><script type="module">import * as lib from "/offline-client.js";window.lib=lib;</script>'));
  app.get('/offline-client.js',(_req,res)=>res.type('application/javascript').send(bundle));
  app.use((req,_res,next)=>{if(req.path.endsWith('/offline/context'))requests.context++;if(req.path.endsWith('/offline/receipt'))requests.receipt++;if(req.method==='POST'&&req.path.endsWith('/trips/commands'))requests.send++;next();});
  app.post('/api/v2/projects/:projectId/offline/receipt',(req,res,next)=>{if(receiptFault){res.status(receiptFault).json({error:{code:'RECEIPT_UNAVAILABLE'}});return;}next();});
  app.post('/api/v2/projects/:projectId/trips/commands',async(req,res,next)=>{
   if(sendFault&&malformedFailure){res.status(sendFault).type('html').send('<html>Unavailable</html>');return;}
   if(sendFault){res.set('Retry-After','60').status(sendFault).json({code:sendFault===409?'TRIP_REVISION_CONFLICT':sendFault===422?'INVALID_MEASUREMENT':sendFault===401?'AUTH_REQUIRED':'UNAVAILABLE'});return;}
   if(drops.delete(req.body.operationId)){await service.execute(req.header('Authorization')!.slice(7),scope,req.body);res.status(200).type('json');res.flushHeaders();res.write('{"incomplete":');setTimeout(()=>res.socket?.destroy(),10);return;}
   const release=delays.get(req.body.operationId);if(release){const result=await service.execute(req.header('Authorization')!.slice(7),scope,req.body);await new Promise<void>(done=>{delays.set(req.body.operationId,done);release();});res.json(result);return;}next();
  });
  app.post('/api/v2/projects/:projectId/imports/:sessionId/executions/:operationId/advance',async(req,res,next)=>{
   if(!drops.delete(req.body.requestId))return next();await importService.advance('SUPER_ADMIN',scope,{...req.body,sessionId:String(req.params.sessionId),operationId:String(req.params.operationId)});res.status(200).type('json');res.flushHeaders();res.write('{"incomplete":');setTimeout(()=>res.socket?.destroy(),10);
  });
  mountIsolatedSqlOfflineRoutes(app,{trips:service,imports:importService,recovery:new SqlOfflineRecoveryAuthority({...deps,backendFence:undefined}),companyForToken:async()=>company,epoch:deps.backendFence});
  server=await new Promise<any>(done=>{const s=app.listen(0,'127.0.0.1',()=>done(s));});url=`http://127.0.0.1:${server.address().port}`;
  browser=await loadBrowser().chromium.launch({executablePath:process.platform==='win32'?executable():process.env.QSA_BROWSER_EXECUTABLE,headless:true,args:['--disable-background-networking','--no-first-run']});
 },60000);
 beforeEach(async()=>{drops.clear();delays.clear();malformedFailure=false;receiptFault=0;sendFault=0;requests={context:0,send:0,receipt:0,google:0};context=await browser.newContext({serviceWorkers:'block'});context.on('request',(r:any)=>{if(/googleapis|sheets\.google|drive\.google/.test(r.url()))requests.google++;});page=await newPage();});
