 test('interrupted SENDING after durable claim uses receipt before retry after reload',async()=>{await configure();const op=await enqueue();await page.evaluate(async(op:any)=>{const w=window as any,db=await w.store.database.getDB();await new Promise<void>(done=>{const t=db.transaction('sqlCommands','readwrite'),s=t.objectStore('sqlCommands'),r=s.get(op.key);r.onsuccess=()=>s.put({...r.result,status:'SENDING',attempts:1,lease:{owner:'crashed',fence:1,until:w.clock+1000}});t.oncomplete=()=>done();});},op);await page.reload();await page.waitForFunction(()=>Boolean((window as any).lib));await configure();await tick();await wake();expect((await ops())[0].status).toBe('SYNCED');expect(requests.receipt).toBeGreaterThan(0);expect(requests.send).toBe(1);});
 test('two actual tabs coordinate a pending operation using durable leases and receipt recovery',async()=>{await configure();const op=await enqueue(),other=await newPage();await configure(other);const before=await counts();await Promise.all([wake(),wake(other)]);expect((await ops())[0].status).toBe('SYNCED');expect((await counts()).trips-before.trips).toBe(1);expect(requests.send).toBe(1);expect((await ops(other))[0].operationId).toBe(op.operationId);});
