 test('RB1 IN_PROGRESS and expired two-tab leases preserve dependency attempts and stop quietly',async()=>{const trip=await dispatch();await configure();const a=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','ARRIVE_ORIGIN',{tripId:trip.tripId},trip.revision),trip),b=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','START_LOADING',{tripId:trip.tripId},trip.revision+1),trip);await page.evaluate(async(a:any)=>{const w=window as any;await w.store.tx(['sqlCommands'],'readwrite',(t:any)=>t.objectStore('sqlCommands').put({...a,status:'SENDING',attempts:1,lease:{owner:'crashed',fence:1,until:w.clock-1}}));},a);const other=await newPage();await configure(other);for(const p of [page,other])await p.evaluate(()=>{const w=window as any;w.recoveries=0;w.transport.receipt=async(op:any)=>{w.recoveries++;return {...op.identity,operationId:op.operationId,requestDigest:op.requestDigest,state:'IN_PROGRESS'};};});for(let i=0;i<4;i++){await tick();await tick(other);await Promise.all([wake(),wake(other)]);}const values=await ops();expect(values.find((v:any)=>v.operationId===a.operationId).status).toBe('REVIEW_REQUIRED');expect(values.find((v:any)=>v.operationId===b.operationId)).toMatchObject({status:'PENDING',attempts:0,recoveries:0});const quiet={...requests};await wake();await wake(other);expect(requests).toEqual(quiet);expect(requests.send).toBe(0);});
 test('RB1 conflict and cancellation never silently release dependent intent',async()=>{const trip=await dispatch();await configure();const a=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','ARRIVE_ORIGIN',{tripId:trip.tripId},trip.revision+99),trip),b=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','START_LOADING',{tripId:trip.tripId},trip.revision+1),trip);await wake();expect((await ops()).find((v:any)=>v.operationId===a.operationId).status).toBe('CONFLICT');const quiet={...requests};await tick();await wake();expect(requests).toEqual(quiet);expect((await ops()).find((v:any)=>v.operationId===b.operationId)).toMatchObject({status:'PENDING',attempts:0});const other=await dispatch();const cancelled=await page.evaluate(async(trip:any)=>{const w=window as any,a=await w.queue.enqueue('TRIP','ARRIVE_ORIGIN',{tripId:trip.tripId},trip.revision);await w.queue.cancel(a.operationId);const b=await w.queue.enqueue('TRIP','START_LOADING',{tripId:trip.tripId},trip.revision+1);return b;},other);await wake();expect((await ops()).find((v:any)=>v.operationId===cancelled.operationId).attempts).toBe(0);expect(requests).toEqual(quiet);});
 test('RB1 restoring authorization and resuming a child does not bypass a blocked predecessor',async()=>{const trip=await dispatch();await configure(page,'DISPATCHER');const a=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','ARRIVE_ORIGIN',{tripId:trip.tripId},trip.revision),trip);drops.add(a.operationId);await wake();const b=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','START_LOADING',{tripId:trip.tripId},trip.revision+1),trip);await admin.query("UPDATE user_company_roles SET status='REVOKED' WHERE company_id=$1 AND user_id=$2",[company,actors.DISPATCHER]);try{await tick();await wake();expect(await ops()).toEqual([]);}finally{await admin.query("UPDATE user_company_roles SET status='ACTIVE' WHERE company_id=$1 AND user_id=$2",[company,actors.DISPATCHER]);}await configure(page,'DISPATCHER');await page.evaluate((id:string)=>(window as any).queue.resume(id),b.operationId);const quiet={...requests};await wake();expect(requests).toEqual(quiet);expect((await ops()).find((v:any)=>v.operationId===b.operationId)).toMatchObject({status:'PENDING',attempts:0});expect((await ops()).find((v:any)=>v.operationId===a.operationId).status).toBe('REVIEW_REQUIRED');});
 test('RB1 import advances keep session group order through uncertain ACK and competing tabs',async()=>{const prepared=await session([row(1),row(2)]),started=await start(prepared);expect(started.operation.groupCount).toBe(2);const cp=await importService.readCheckpoint('SUPER_ADMIN',scope,prepared.sessionId),refs={sessionId:prepared.sessionId,operationId:prepared.operationId,reviewedSignature:sha(cp.reviewedCanonicalIntent.intent.signature),sourceRevisionId:cp.source.sourceRevisionId,mappingRevisionId:cp.mapping.mappingRevisionId};await configure();const a=await page.evaluate(async({refs,version}:any)=>(window as any).queue.enqueue('IMPORT_ADVANCE','ADVANCE_IMPORT',{...refs,expectedVersion:version},version),{refs,version:started.operation.version});drops.add(a.operationId);await wake();const current=await importService.status('SUPER_ADMIN',scope,prepared.sessionId,prepared.operationId);expect(current.operation.completedGroups).toBe(1);const b=await page.evaluate(async({refs,version}:any)=>(window as any).queue.enqueue('IMPORT_ADVANCE','ADVANCE_IMPORT',{...refs,expectedVersion:version},version),{refs,version:current.operation.version});const other=await newPage();await configure(other);receiptFault=503;await tick();await tick(other);await Promise.all([wake(),wake(other)]);expect((await ops()).find((v:any)=>v.operationId===b.operationId)).toMatchObject({status:'PENDING',attempts:0});expect((await importService.status('SUPER_ADMIN',scope,prepared.sessionId,prepared.operationId)).operation.completedGroups).toBe(1);receiptFault=0;await tick();await wake();await wake();expect((await ops()).find((v:any)=>v.operationId===b.operationId).status).toBe('SYNCED');expect((await importService.status('SUPER_ADMIN',scope,prepared.sessionId,prepared.operationId)).operation.state).toBe('COMPLETED');});
 test('RB1 atomic equal-time appends and bounded scheduling progress beyond 100 independent entries',async()=>{await configure();const result=await page.evaluate(async()=>{const w=window as any;w.clock=Date.parse('2026-11-09T00:00:00Z');for(let i=0;i<110;i++)await w.queue.enqueue('TRIP','ARRIVE_ORIGIN',{tripId:'isolated-'+i},1);const all=await w.store.tx(['sqlCommands'],'readonly',(t:any,set:any)=>{t.objectStore('sqlCommands').getAll().onsuccess=(e:any)=>set(e.target.result);});w.sends=0;w.transport.send=async()=>{w.sends++;throw Object.assign(Error('OFFLINE'),{status:503});};const trace=[];for(let i=0;i<4;i++){await w.queue.wake();trace.push(w.sends);}return {orders:all.map((o:any)=>o.submissionOrder).sort((a:number,b:number)=>a-b),times:new Set(all.map((o:any)=>o.createdAt)).size,trace};});expect(result.orders).toEqual(Array.from({length:110},(_,i)=>i+1));expect(result.times).toBe(1);expect(result.trace[0]).toBe(0);expect(result.trace[1]).toBe(100);expect(result.trace[2]).toBe(110);expect(result.trace[3]).toBe(110);});
 test('RB1 pre-correction v3 intent is preserved for review and blocks new dependent claims',async()=>{const trip=await dispatch();await configure();const a=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','ARRIVE_ORIGIN',{tripId:trip.tripId},trip.revision),trip);await page.evaluate(async(a:any)=>{const w=window as any,{submissionOrder,causalKey,predecessorKey,...legacy}=a;await w.store.tx(['sqlCommands','sqlControl'],'readwrite',(t:any)=>{t.objectStore('sqlCommands').put(legacy);const q=t.objectStore('sqlControl').openCursor();q.onsuccess=()=>{const c=q.result;if(c){if(['submission/','tail/','schedule/','scheduler/','ordering-bootstrap/'].some(prefix=>String(c.key).startsWith(prefix)))c.delete();c.continue();}};});},a);const b=await page.evaluate(async(trip:any)=>(window as any).queue.enqueue('TRIP','START_LOADING',{tripId:trip.tripId},trip.revision+1),trip);await wake();const values=await ops();expect(values.find((v:any)=>v.operationId===a.operationId)).toMatchObject({status:'REVIEW_REQUIRED',errorCode:'CAUSAL_ORDER_UNVERIFIED',requestDigest:a.requestDigest,envelope:a.envelope});expect(values.find((v:any)=>v.operationId===b.operationId)).toMatchObject({status:'PENDING',attempts:0});expect(requests.send).toBe(0);});
 test('RB1 absent authoritative creation identity requires explicit reconciliation without payload injection',async()=>{await configure();const op=await enqueue();const result=await page.evaluate(async()=>{const w=window as any;try{await w.queue.enqueue('TRIP','START_LOADING',{},1);return '';}catch(e:any){return e.code;}});expect(result).toBe('AUTHORITATIVE_TRIP_ID_REQUIRED');expect((await ops())[0].envelope).toEqual(op.envelope);});
 for(const fault of ['completeThrough','filtered','interrupted','account','project','epoch','generation'])test(`RB1 ${fault} completeness cannot delete scoped cached records`,async()=>{await configure();const ids=await page.evaluate(async(fault:string)=>{const w=window as any,id=await w.transport.context(w.queue['session'].scope,new AbortController().signal),base={identity:id,kind:'FLEET',sourceRevision:'1',cursor:null,nextCursor:null,hasMore:false,fullSnapshot:false,items:[{id:'A',revision:5},{id:'B',revision:5}]};let t=w.queue.beginInventory('FLEET','1');await w.queue.acceptPage(t,base);t=w.queue.beginInventory('FLEET','2');const p:any={...base,sourceRevision:'2',fullSnapshot:true,completeThrough:'2',items:[{id:'A',revision:2}]};if(fault==='completeThrough')p.completeThrough='FORGED';if(fault==='filtered')p.filter={status:'ACTIVE'};if(fault==='interrupted'){await w.queue.acceptPage(t,{...p,fullSnapshot:false,hasMore:true,nextCursor:'remaining',items:[]});}if(fault==='account')p.identity={...id,principal:'another'};if(fault==='project')p.identity={...id,projectId:'another'};if(fault==='epoch')p.identity={...id,epochRevision:id.epochRevision+1};if(fault==='generation')await w.queue.enter(id.companyId,id.projectId);try{await w.queue.acceptPage(t,p);}catch{}return (await w.queue.cache()).map((v:any)=>({id:v.data.id,revision:v.data.revision})).sort((a:any,b:any)=>a.id.localeCompare(b.id));},fault);expect(ids).toEqual([{id:'A',revision:5},{id:'B',revision:5}]);});
 test('database epoch changes wait for in-flight transactions and fence stale writers forward-only',async()=>{await configure();await enqueue();const payload=await fleet(false);const held=await runtime.connect();try{await held.query('BEGIN');await held.query('SELECT qsa_assert_offline_epoch($1,1)',[SQL_TRIP_EPOCH]);let changed=false;const change=admin.query('UPDATE backend_authority_epoch SET epoch_revision=2 WHERE singleton').then(()=>changed=true);await new Promise(r=>setTimeout(r,100));expect(changed).toBe(false);await held.query('COMMIT');await change;await wake();expect((await ops())[0].status).toBe('QUARANTINED_EPOCH');await expect(service.execute('SUPER_ADMIN',scope,envelope('DISPATCH_TRIP',payload))).rejects.toMatchObject({code:'BACKEND_EPOCH_MISMATCH'});await expect(admin.query('UPDATE backend_authority_epoch SET epoch_revision=1 WHERE singleton')).rejects.toHaveProperty('code','23514');await expect(runtime.query('UPDATE backend_authority_epoch SET epoch_revision=3')).rejects.toHaveProperty('code','42501');}finally{held.release();}});
